INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0.5, 19050041, 1, 0, "シズルさまにエリコさま、\nどうかされたのですか？", 11, 10, 905, 0, 107611, 0);
