INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0.5, 19230017, 1, 0, "ここメルクリゾートではプールサイドで\nたい焼きを売る怪人の噂がある。", 11, 10, 923, 0, 115711, 0);
