INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0.5, 19230021, 1, 0, "フードコートで売っているのであれば\n何ら違和感はないけれど。", 11, 10, 923, 0, 115711, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", 19230022, "", "", "", 91, "", 923, "", 0, "");
