INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (1, 19440025, 1, 0, "はい、そこの流れてくるおねーさん\nたい焼きいかがかにゃ？", 11, 8, 944, 0, 107911, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", 19440026, "", "", "", 91, "", 944, "", 0, "");
