INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0.5, 19440046, 1, 0, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 11, 8, 944, 0, 107911, 0);
